            ],
            "attacker_controlled": true,
            "validation_layers": [
              "ECDSA signature recovery",
              "SECP256K1 curve operations"
            ],
            "bug_bounty_scope": "in-scope",
            "notes": "Transaction sender authentication is fundamental to Ethereum security."
          },
          "test_procedure": "1. Trace the code path from P2P transaction receipt to sender recovery and subsequent processing.\n2. Verify that the execution client does not cache or trust sender addresses from external sources.\n3. Confirm that sender recovery is performed independently by the execution client using the raw signature.\n4. Check that recovered sender is used consistently throughout transaction validation and execution.\n5. Verify no TOCTOU vulnerabilities exist between sender verification and transaction execution.",
          "bug_class": "Input Validation",
          "risk_category": "Spoofing",
          "notes": "Source: PROP-W5B6-60, Supporting Node: actor-execution-client"
